inline std::vector<ZoneTriggerVolume::Volume> authoredVolumes;
inline std::vector<ZoneTriggerVolume::Volume> arrivalVolumes;
// Server-script event regions, kept separate from decoded RID records.
inline const ZoneTriggerVolume::Volume towerPortals[] = {
    {{0,-16.5f,141},{4,1,2},0,ZoneTriggerVolume::Token("htin"),1,239},
    {{0,0,-34},{2,2,2},0,ZoneTriggerVolume::Token("hout"),1,242},
    {{7,-45,-29},{2,2,2},0,ZoneTriggerVolume::Token("hret"),1,242},
};
inline const ZoneTriggerVolume::Volume* VolumeFor(const Line& line)
{
    const char* token = line.token;
    if (std::strcmp(token, "mh_bm_n") == 0) token = "zmrc";
    if (std::strcmp(token, "mh_bm_s") == 0) token = "zmra";
    for (const auto& volume : authoredVolumes)
        if (volume.id == ZoneTriggerVolume::Token(token)) return &volume;
    for (const auto& volume : towerPortals)
        if (volume.zone == line.fromZone && volume.id == ZoneTriggerVolume::Token(token)) return &volume;
    return nullptr;
}

inline bool MarkerFloorEligible(const Line& line, const Point& playerNative)
{
    if (const auto* volume = VolumeFor(line))
        return std::fabs(playerNative[1]-volume->center[1]) < volume->size[1]*0.5f;
    return std::fabs(playerNative[1]-line.threshold[1]) <= 4.0f;
}

inline const Line* Crossed(int zone, const Point& sceneStart, const Point& sceneEnd, bool mirrorX)
{
    const Point a = FFXICoordinateFrame::SceneToNativeDat(sceneStart, mirrorX);
    const Point b = FFXICoordinateFrame::SceneToNativeDat(sceneEnd, mirrorX);
    for (const auto& portal : towerPortals)
    {
        if (portal.zone != zone) continue;
        // Event-region boundaries include the floor; RID bounds stay strict.
        auto bounds=portal;
        for (auto& size : bounds.size) size += 0.002f;
        if (!ZoneTriggerVolume::Hit(bounds,a,b)) continue;
        for (const auto& line : lines)
            if (line.fromZone==zone && ZoneTriggerVolume::Token(line.token)==portal.id) return &line;
    }
    // Retail returns the first matching RID record, including a stationary
    // actor inside a volume. Destination routing remains DATura policy.
    if (!authoredVolumes.empty())
    {
        for (const auto& volume : authoredVolumes)
        {
            if (!ZoneTriggerVolume::Hit(volume, a, b)) continue;
            for (const auto& line : lines)
                if (line.fromZone == zone && VolumeFor(line) == &volume) return &line;
            // Retail selects this record first even when DATura has no local
            // destination for its token; do not substitute an overlapping one.
            return nullptr;
        }
        return nullptr;
    }
    const Line* found = nullptr;
    float first = 2;
    for (const Line& line : lines)
    {
        if (line.fromZone != zone) continue;
        const float start = (a[0]-line.threshold[0])*line.outward[0] + (a[2]-line.threshold[2])*line.outward[2];
        const float end = (b[0]-line.threshold[0])*line.outward[0] + (b[2]-line.threshold[2])*line.outward[2];
        if (!(start < 0 && end >= 0)) continue;
        const float t = -start / (end-start);
        const float x = a[0] + t*(b[0]-a[0]) - line.threshold[0];
        const float z = a[2] + t*(b[2]-a[2]) - line.threshold[2];
        const float y = a[1] + t*(b[1]-a[1]) - line.threshold[1];
        if (std::fabs(x*line.outward[2] - z*line.outward[0]) > line.halfWidth || std::fabs(y) > 4) continue;
        if (t < first) { first = t; found = &line; }
    }
    return found;
}

inline float ArrivalYaw(const Line& line, bool mirrorX)
{
    return FFXICoordinateFrame::NativeDatHeadingToScene(
        DecodeHeading(line.heading), mirrorX) - 1.57079632679f;
}
